INSERT INTO notasys.emisor(ruc_emisor,razon_social_emisor) SELECT ruc_emisor,razon_social_emisor FROM public.emisor;
INSERT INTO notasys.cliente(documento_cliente,razon_social_cliente) SELECT documento_cliente,razon_social_cliente FROM public.cliente;
INSERT INTO notasys.producto(codigo_producto,descripcion,unidad_medida) SELECT codigo_producto,descripcion,unidad_medida FROM public.producto;
INSERT INTO notasys.factura(serie,correlativo,ruc_emisor,fecha_emision,documento_cliente,tipo_moneda,valor_venta,igv,importe_total) SELECT serie,CASE WHEN correlativo IS NULL THEN NULL ELSE lpad(correlativo,8,'0') END,ruc_emisor,fecha_emision,documento_cliente,tipo_moneda,valor_venta,igv,importe_total FROM public.factura;
INSERT INTO notasys.detalle_factura(ruc_emisor,serie,correlativo,codigo_producto,descripcion_historica,cantidad,valor_unitario) SELECT h.ruc_emisor,d.serie,lpad(d.correlativo,8,'0'),d.codigo_producto,p.descripcion,d.cantidad,d.valor_unitario FROM public.detalle_factura d JOIN public.factura h USING(serie,correlativo) JOIN public.producto p USING(codigo_producto);
INSERT INTO notasys.boleta(serie,correlativo,ruc_emisor,fecha_emision,documento_cliente,tipo_moneda,valor_venta,igv,importe_total) SELECT serie,CASE WHEN correlativo IS NULL THEN NULL ELSE lpad(correlativo,8,'0') END,ruc_emisor,fecha_emision,documento_cliente,tipo_moneda,valor_venta,igv,importe_total FROM public.boleta;
INSERT INTO notasys.detalle_boleta(ruc_emisor,serie,correlativo,codigo_producto,descripcion_historica,cantidad,valor_unitario) SELECT h.ruc_emisor,d.serie,lpad(d.correlativo,8,'0'),d.codigo_producto,p.descripcion,d.cantidad,d.valor_unitario FROM public.detalle_boleta d JOIN public.boleta h USING(serie,correlativo) JOIN public.producto p USING(codigo_producto);
INSERT INTO notasys.nota_credito(serie,correlativo,ruc_emisor,fecha_emision,documento_cliente,moneda,motivo,descripcion_ajuste,serie_factura,correlativo_factura,serie_boleta,correlativo_boleta,valor_venta,igv,importe_total) SELECT serie,CASE WHEN correlativo IS NULL THEN NULL ELSE lpad(correlativo,8,'0') END,ruc_emisor,fecha_emision,documento_cliente,moneda,motivo,descripcion_ajuste,serie_factura,CASE WHEN correlativo_factura IS NULL THEN NULL ELSE lpad(correlativo_factura,8,'0') END,serie_boleta,CASE WHEN correlativo_boleta IS NULL THEN NULL ELSE lpad(correlativo_boleta,8,'0') END,valor_venta,igv,importe_total FROM public.nota_credito;
INSERT INTO notasys.detalle_nota_credito(ruc_emisor,serie,correlativo,codigo_producto,descripcion_historica,cantidad,valor_unitario) SELECT h.ruc_emisor,d.serie,lpad(d.correlativo,8,'0'),d.codigo_producto,p.descripcion,d.cantidad,d.valor_unitario FROM public.detalle_nota_credito d JOIN public.nota_credito h USING(serie,correlativo) JOIN public.producto p USING(codigo_producto);
INSERT INTO notasys.nota_debito(serie,correlativo,ruc_emisor,fecha_emision,documento_cliente,moneda,motivo,descripcion_ajuste,serie_factura,correlativo_factura,serie_boleta,correlativo_boleta,valor_venta,igv,importe_total) SELECT serie,CASE WHEN correlativo IS NULL THEN NULL ELSE lpad(correlativo,8,'0') END,ruc_emisor,fecha_emision,documento_cliente,moneda,motivo,descripcion_ajuste,serie_factura,CASE WHEN correlativo_factura IS NULL THEN NULL ELSE lpad(correlativo_factura,8,'0') END,serie_boleta,CASE WHEN correlativo_boleta IS NULL THEN NULL ELSE lpad(correlativo_boleta,8,'0') END,valor_venta,igv,importe_total FROM public.nota_debito;
INSERT INTO notasys.detalle_nota_debito(ruc_emisor,serie,correlativo,codigo_producto,descripcion_historica,cantidad,valor_unitario) SELECT h.ruc_emisor,d.serie,lpad(d.correlativo,8,'0'),d.codigo_producto,p.descripcion,d.cantidad,d.valor_unitario FROM public.detalle_nota_debito d JOIN public.nota_debito h USING(serie,correlativo) JOIN public.producto p USING(codigo_producto);
